"""Validators over depot run outputs.

Each validator measures a non-empty list of per-item records. If no item could be
measured, the list is empty and `Check.run` reports "failed: nothing measured",
so a validator never passes on nothing.
"""
from __future__ import annotations

from checks_base import Check, is_empty

# Notification types the spec says the depot emits.
SPEC_NOTIFICATION_TYPES = frozenset(
    {"SUPPLIER_SUSPENDED", "OVERDRAWN", "REORDER", "EXPIRY", "AUDIT_MISMATCH"}
)


class V1(Check):
    """Every report row's value_cents equals units * unit_cost."""

    name = "V1"

    def check(self, rows):
        records = []
        ok = True
        for r in rows:
            expected = r["units"] * r["unit_cost"]
            records.append((r["sku"], r["wh"], expected, r["value_cents"]))
            if expected != r["value_cents"]:
                ok = False
        return (ok and len(records) > 0), records


class V2(Check):
    """All spec notification types were seen across the runs."""

    name = "V2"

    def check(self, runs):
        seen = set()
        for run in runs:
            for n in run:
                seen.add(n[0])
        missing = sorted(SPEC_NOTIFICATION_TYPES - seen)
        measured = {"seen": sorted(seen & SPEC_NOTIFICATION_TYPES), "missing": missing}
        return (not missing), measured


class V3(Check):
    """Two runs with the same seed are identical."""

    name = "V3"

    def check(self, pairs):
        records = []
        ok = True
        for p in pairs:
            if is_empty(p["a"]) and is_empty(p["b"]):
                continue  # two empty outputs prove nothing; not measured
            same = p["a"] == p["b"]
            records.append((p["seed"], same))
            if not same:
                ok = False
        return (ok and len(records) > 0), records


class V4(Check):
    """Storage cost stayed within the budget on every day."""

    name = "V4"

    def check(self, days):
        records = []
        ok = True
        for d in days:
            cost, budget = d["storage_cost_cents"], d["budget_cents"]
            records.append((d["day"], cost, budget))
            if cost > budget:
                ok = False
        return (ok and len(records) > 0), records


class V5(Check):
    """Every clause has at least one test (non-empty test name)."""

    name = "V5"

    def check(self, clauses):
        records = []
        ok = True
        for c in clauses:
            n = sum(1 for t in c["tests"] if isinstance(t, str) and t.strip())
            records.append((c["clause_id"], n))
            if n < 1:
                ok = False
        return (ok and len(records) > 0), records


class V6(Check):
    """Results from two implementations agree on every compared pair."""

    name = "V6"

    def check(self, pairs):
        records = []
        ok = True
        for p in pairs:
            if is_empty(p["a"]) and is_empty(p["b"]):
                continue  # both empty: nothing was actually compared
            same = p["a"] == p["b"]
            records.append((p["key"], same))
            if not same:
                ok = False
        return (ok and len(records) > 0), records
```

`checks_base.py`:

```
"""The ``Check`` base class: a check never passes on nothing (brief 3, and E2's guard condition).

``Check.run(items)`` returns ``failed: empty input`` for empty or all-unmeasured input *before*
calling the subclass, and ``failed: nothing measured`` when the subclass measured nothing. The
harness's own checks (presence, reach, parity, mutation) subclass it, and so do the agent's
validators in E2's guard condition (the agent gets this file as ``checks_base.py``).

This file is standard-library only so it can be copied verbatim into the agent's repo.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class CheckResult:
    passed: bool
    measured: Any
    reason: str = ""

    def __iter__(self):  # allows ``passed, measured = check.run(x)``
        yield self.passed
        yield self.measured

    def __bool__(self) -> bool:
        return bool(self.passed)


def is_empty(value: Any) -> bool:
    """True for None, empty containers, and containers whose every leaf is None or empty."""
    if value is None:
        return True
    if isinstance(value, (str, bytes)):
        return len(value) == 0
    if isinstance(value, dict):
        return len(value) == 0 or all(is_empty(v) for v in value.values())
    if isinstance(value, (list, tuple, set, frozenset)):
        return len(value) == 0 or all(is_empty(v) for v in value)
    return False


class Check:
    """Subclasses implement ``check(items) -> (passed, measured)``; callers use ``run(items)``."""

    name = "check"

    def run(self, items: Any) -> CheckResult:
        if hasattr(items, "__next__"):  # a lazy source of runs: materialise before judging emptiness
            items = list(items)
        if is_empty(items):
            return CheckResult(False, None, "failed: empty input")
        try:
            passed, measured = self.check(items)
        except Exception as exc:  # a check that crashes has not passed
            return CheckResult(False, None, f"failed: {type(exc).__name__}: {exc}")
        if is_empty(measured):
            return CheckResult(False, measured, "failed: nothing measured")
        return CheckResult(bool(passed), measured, "" if passed else "failed")

    def check(self, items: Any) -> tuple[bool, Any]:  # pragma: no cover - abstract
        raise NotImplementedError
```

