<file path="validators_later.py">
"""Later validators over depot run outputs, in the same form as `validators.py`.

Each validator measures a non-empty list of per-item records. If nothing could be
measured, the list is empty and `Check.run` reports "failed: nothing measured".
"""
from __future__ import annotations

from collections import Counter

from checks_base import Check, is_empty

# Inclusive bounds for a supplier's reliability score.
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


class V7(Check):
    """Every warehouse's capacity was respected across runs."""

    name = "V7"

    def check(self, entries):
        records = []
        ok = True
        for e in entries:
            records.append((e["wh"], e["max_units"], e["capacity"]))
            if e["max_units"] > e["capacity"]:
                ok = False
        return (ok and len(records) > 0), records


class V8(Check):
    """All expiries were notified."""

    name = "V8"

    def check(self, entries):
        records = []
        ok = True
        for i, e in enumerate(entries):
            if is_empty(e["expired"]):
                continue  # nothing expired: nothing to verify, not measured
            expired = Counter(tuple(x) for x in e["expired"])
            notified = Counter(tuple(x) for x in e["notified"])
            missing = sorted((expired - notified).elements())
            records.append((i, len(e["expired"]), missing))
            if missing:
                ok = False
        return (ok and len(records) > 0), records


class V9(Check):
    """Every supplier's reliability stayed in range."""

    name = "V9"

    def check(self, entries):
        records = []
        ok = True
        for e in entries:
            r = e["reliability"]
            records.append((e["supplier"], r))
            if not (RELIABILITY_MIN <= r <= RELIABILITY_MAX):
                ok = False
        return (ok and len(records) > 0), records
