<file path="test_validators_later.py">
import unittest

from validators_later import V7, V8, V9


class TestV7(unittest.TestCase):
    def test_pass_and_boundary(self):
        r = V7().run([{"wh": "a", "capacity": 10, "max_units": 10}])
        self.assertTrue(r.passed)

    def test_fail(self):
        r = V7().run([{"wh": "a", "capacity": 10, "max_units": 11}])
        self.assertFalse(r.passed)

    def test_empty(self):
        self.assertFalse(V7().run([]).passed)


class TestV8(unittest.TestCase):
    def test_pass(self):
        e = {"expired": [["s", "w", 2]], "notified": [["s", "w", 2], ["x", "w", 1]]}
        self.assertTrue(V8().run([e]).passed)

    def test_missing(self):
        e = {"expired": [["s", "w", 2]], "notified": [["s", "w", 3]]}
        self.assertFalse(V8().run([e]).passed)

    def test_duplicate_expiry_needs_two_notices(self):
        e = {"expired": [["s", "w", 2], ["s", "w", 2]], "notified": [["s", "w", 2]]}
        self.assertFalse(V8().run([e]).passed)

    def test_nothing_expired_is_not_measured(self):
        r = V8().run([{"expired": [], "notified": [["s", "w", 1]]}])
        self.assertFalse(r.passed)
        self.assertEqual(r.reason, "failed: nothing measured")


class TestV9(unittest.TestCase):
    def test_pass(self):
        self.assertTrue(V9().run([{"supplier": "s", "reliability": 0},
                                  {"supplier": "t", "reliability": 100}]).passed)

    def test_out_of_range(self):
        self.assertFalse(V9().run([{"supplier": "s", "reliability": 101}]).passed)
        self.assertFalse(V9().run([{"supplier": "s", "reliability": -1}]).passed)

    def test_empty(self):
        self.assertFalse(V9().run([]).passed)


if __name__ == "__main__":
    unittest.main()
</file>

<notes>
- The spec doesn't define V9's "range", so I assumed an inclusive 0..100, set by `RELIABILITY_MIN` and `RELIABILITY_MAX`. Please confirm or give the real bounds.
- V7 passes when `max_units <= capacity`, so exactly at capacity counts as respected.
- V8 compares `[sku, wh, qty]` triples exactly, counting duplicates. Entries with no expiries are skipped as not measured, as V3 and V6 do for empty pairs. The record for each entry is `(index, expired_count, missing)`.
</notes>
